11: module.exports = function link(state, silent) {
12:   var attrs,
13:       code,
14:       href,
15:       label,
16:       labelEnd,
17:       labelStart,
18:       pos,
19:       res,
20:       ref,
21:       title,
22:       token,
23:       oldPos = state.pos,
24:       max = state.posMax,
25:       start = state.pos;
