27:   if (state.src.charCodeAt(state.pos) !== 0x5B/* [ */) { return false; }
28: 
29:   labelStart = state.pos + 1;
30:   labelEnd = parseLinkLabel(state, state.pos, true);
31: 
32:   // parser failed to find ']', so it's not a valid link
33:   if (labelEnd < 0) { return false; }
34: 
35:   pos = labelEnd + 1;
36:   if (pos < max && state.src.charCodeAt(pos) === 0x28/* ( */) {
37:     //
38:     // Inline link
39:     //
40: 
41:     // [link](  <href>  "title"  )
42:     //        ^^ skipping these spaces
43:     pos++;
44:     for (; pos < max; pos++) {
45:       code = state.src.charCodeAt(pos);
46:       if (code !== 0x20 && code !== 0x0A) { break; }
47:     }
48:     if (pos >= max) { return false; }
49: 
50:     // [link](  <href>  "title"  )
51:     //          ^^^^^^ parsing link destination
52:     start = pos;
53:     res = parseLinkDestination(state.src, pos, state.posMax);
54:     if (res.ok && state.md.validateLink(res.str)) {
55:       href = res.str;
56:       pos = res.pos;
57:     } else {
58:       href = '';
59:     }
60: 
61:     // [link](  <href>  "title"  )
62:     //                ^^ skipping these spaces
63:     start = pos;
64:     for (; pos < max; pos++) {
65:       code = state.src.charCodeAt(pos);
66:       if (code !== 0x20 && code !== 0x0A) { break; }
67:     }
68: 
