70:     //                  ^^^^^^^ parsing link title
71:     res = parseLinkTitle(state.src, pos, state.posMax);
72:     if (pos < max && start !== pos && res.ok) {
73:       title = res.str;
74:       pos = res.pos;
75: 
76:       // [link](  <href>  "title"  )
77:       //                         ^^ skipping these spaces
78:       for (; pos < max; pos++) {
79:         code = state.src.charCodeAt(pos);
80:         if (code !== 0x20 && code !== 0x0A) { break; }
81:       }
82:     } else {
83:       title = '';
84:     }
