118:     if (!label) { label = state.src.slice(labelStart, labelEnd); }
119: 
120:     ref = state.env.references[normalizeReference(label)];
121:     if (!ref) {
122:       state.pos = oldPos;
123:       return false;
124:     }
125:     href = ref.href;
126:     title = ref.title;
127:   }
