131:   // so all that's left to do is to call tokenizer.
132:   //
133:   if (!silent) {
134:     state.pos = labelStart;
135:     state.posMax = labelEnd;
136: 
137:     token        = state.push('link_open', 'a', 1);
138:     token.attrs  = attrs = [ [ 'href', href ] ];
